import{_ as a,o,c as i,a3 as s}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1786258579000}'),t={name:"faq.md"};function d(r,e,n,l,c,h){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>按「<strong>现象 → 原因 → 解决</strong>」组织的高频故障速查表。每条都对照仓库源码核实过，看到相同现象直接照做。</p><nav class="table-of-contents"><ul><li><a href="#启动与环境">启动与环境</a><ul><li><a href="#后端和前端各自跑在哪个端口">后端和前端各自跑在哪个端口？</a></li><li><a href="#前端报跨域-cors">前端报跨域（CORS）</a></li><li><a href="#启动报-redis-wrongpass">启动报 Redis WRONGPASS</a></li><li><a href="#表没建好-首次启动就登录不了">表没建好 / 首次启动就登录不了</a></li><li><a href="#初始超管账号是什么">初始超管账号是什么？</a></li><li><a href="#不想要演示数据">不想要演示数据</a></li></ul></li><li><a href="#认证与令牌">认证与令牌</a><ul><li><a href="#怎么获取-token">怎么获取 token？</a></li><li><a href="#登录一直提示账号或密码错误">登录一直提示账号或密码错误</a></li><li><a href="#接口一直-401-甚至陷入「刷新-→-401-→-刷新」">接口一直 401，甚至陷入「刷新 → 401 → 刷新」</a></li><li><a href="#接口返回-423-前端弹回了登录页">接口返回 423，前端弹回了登录页</a></li><li><a href="#给用户加了权限-需要重新登录才生效吗">给用户加了权限，需要重新登录才生效吗？</a></li><li><a href="#切换租户会不会把我原来的登录顶掉">切换租户会不会把我原来的登录顶掉？</a></li></ul></li><li><a href="#权限与菜单">权限与菜单</a><ul><li><a href="#新加的菜单在前端不显示">新加的菜单在前端不显示</a></li><li><a href="#菜单出来了-但点进去-404-白屏">菜单出来了，但点进去 404 / 白屏</a></li><li><a href="#我有这个权限码-接口还是-403">我有这个权限码，接口还是 403</a></li><li><a href="#列表少了几列-排序点了没反应">列表少了几列 / 排序点了没反应</a></li></ul></li><li><a href="#接口与联调">接口与联调</a><ul><li><a href="#新加的分页方法收不到请求体">新加的分页方法收不到请求体</a></li><li><a href="#生成的路由和我预期的不一样">生成的路由和我预期的不一样</a></li><li><a href="#返回的-id-变成了字符串">返回的 ID 变成了字符串</a></li><li><a href="#响应里某个字段整个不见了">响应里某个字段整个不见了</a></li><li><a href="#oauthproviders-还是-oauthproviders">oAuthProviders 还是 oauthProviders？</a></li><li><a href="#时间显示差了几个小时">时间显示差了几个小时</a></li><li><a href="#枚举值到底发数字还是发字符串">枚举值到底发数字还是发字符串？</a></li></ul></li><li><a href="#后端开发">后端开发</a><ul><li><a href="#运行期-di-解析不到我的领域服务">运行期 DI 解析不到我的领域服务</a></li><li><a href="#我覆盖了框架的默认实现-但跑起来还是默认的">我覆盖了框架的默认实现，但跑起来还是默认的</a></li><li><a href="#事件处理器不触发">事件处理器不触发</a></li><li><a href="#匿名-minimal-api-端点调应用服务时永久挂起">匿名 Minimal API 端点调应用服务时永久挂起</a></li><li><a href="#数据变更日志-diff-一条都没有">数据变更日志（Diff）一条都没有</a></li><li><a href="#部署后接口报-42703-column-does-not-exist">部署后接口报 42703 column does not exist</a></li><li><a href="#本地-dotnet-build-报文件被占用">本地 dotnet build 报文件被占用</a></li></ul></li><li><a href="#前端">前端</a><ul><li><a href="#页面整片白屏-控制台报-invalid-linked-format">页面整片白屏，控制台报 Invalid linked format</a></li><li><a href="#图标显示成空白">图标显示成空白</a></li><li><a href="#上传的文件在线上打不开-404">上传的文件在线上打不开（404）</a></li><li><a href="#跑-lint-把不相干的文件改坏了">跑 lint 把不相干的文件改坏了</a></li></ul></li><li><a href="#部署与运维">部署与运维</a><ul><li><a href="#升级版本要写数据迁移吗">升级版本要写数据迁移吗？</a></li><li><a href="#启用-ai-知识库-rag-前要准备什么">启用 AI 知识库（RAG）前要准备什么？</a></li><li><a href="#怎么定位一次线上请求">怎么定位一次线上请求？</a></li></ul></li><li><a href="#还没解决">还没解决？</a></li></ul></nav><hr><h2 id="启动与环境" tabindex="-1">启动与环境 <a class="header-anchor" href="#启动与环境" aria-label="Permalink to &quot;启动与环境&quot;">​</a></h2><h3 id="后端和前端各自跑在哪个端口" tabindex="-1">后端和前端各自跑在哪个端口？ <a class="header-anchor" href="#后端和前端各自跑在哪个端口" aria-label="Permalink to &quot;后端和前端各自跑在哪个端口？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>进程</th><th>端口</th><th>备注</th></tr></thead><tbody><tr><td>后端 Development</td><td><code>9708</code></td><td>API 文档 <code>http://127.0.0.1:9708/scalar</code></td></tr><tr><td>后端 Production</td><td><code>9708</code>（仓库默认）</td><td>可由 <code>Hosting:Urls</code> / 容器端口映射覆盖</td></tr><tr><td>前端 dev server</td><td><code>9800</code></td><td><code>VITE_PORT</code></td></tr></tbody></table><p>开发态前端<strong>不直连后端</strong>：<code>VITE_API_BASE_URL</code> 留空，请求打到自己的 dev server，再由 Vite 代理转发到 <code>VITE_DEV_PROXY_TARGET</code>（默认 <code>http://localhost:9708</code>）——同源转发，天然没有 CORS 问题。</p><div class="tip custom-block"><p class="custom-block-title">改后端端口后前端连不上</p><p>改的是 <code>Hosting:Urls</code> 或 launch profile，别忘了同步改 <code>frontend/.env.development</code> 的 <code>VITE_DEV_PROXY_TARGET</code>。</p></div><h3 id="前端报跨域-cors" tabindex="-1">前端报跨域（CORS） <a class="header-anchor" href="#前端报跨域-cors" aria-label="Permalink to &quot;前端报跨域（CORS）&quot;">​</a></h3><p>生产部署前后端<strong>不同源</strong>时才会遇到。三条路，选一条：</p><ol><li>前端与 API 同域，由 Nginx 反向代理 <code>/api</code>（推荐，仓库自带 <code>frontend/nginx.conf</code>）。</li><li>配后端网关的 <code>Gateway.AllowedOrigins</code> 放行前端源。</li><li>开发期保持走 Vite 代理，别把 <code>VITE_API_BASE_URL</code> 填成后端绝对地址。</li></ol><h3 id="启动报-redis-wrongpass" tabindex="-1">启动报 Redis <code>WRONGPASS</code> <a class="header-anchor" href="#启动报-redis-wrongpass" aria-label="Permalink to &quot;启动报 Redis `WRONGPASS`&quot;">​</a></h3><p>仓库默认连接串用的是 <strong>ACL 用户</strong> <code>user=redis,password=redis</code>，而官方 <code>redis</code> 镜像默认既无密码也没有名为 <code>redis</code> 的用户。按 <a href="./dev-environment#redis-6-生产多实例必需">开发环境</a> 里的 <code>docker run</code> 命令建好同名 ACL 用户即可；本地图省事也可以把 <code>XiHan:Caching:Redis:IsEnabled</code> 设为 <code>false</code> 退化成进程内内存缓存（会失去分布式缓存/锁/队列）。</p><h3 id="表没建好-首次启动就登录不了" tabindex="-1">表没建好 / 首次启动就登录不了 <a class="header-anchor" href="#表没建好-首次启动就登录不了" aria-label="Permalink to &quot;表没建好 / 首次启动就登录不了&quot;">​</a></h3><p>全新数据库首次启动会<strong>自动建表 + 播种子数据</strong>。初始化中途失败时，可在确认没有业务数据后删库重试；存量数据库不要直接删除，应先核对 <code>UpdateScripts</code> 与实际迁移入口，见<a href="#部署后接口报-42703-column-does-not-exist">下文</a>。</p><h3 id="初始超管账号是什么" tabindex="-1">初始超管账号是什么？ <a class="header-anchor" href="#初始超管账号是什么" aria-label="Permalink to &quot;初始超管账号是什么？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>值</th></tr></thead><tbody><tr><td>账号</td><td><code>superadmin</code></td></tr><tr><td>密码</td><td><code>SuperAdmin@123</code></td></tr></tbody></table><p>初始密码可用配置 <code>Saas:Seed:SuperAdminPassword</code>（环境变量写法 <code>Saas__Seed__SuperAdminPassword</code>）覆盖。<strong>生产务必覆盖，并在首次登录后立即修改。</strong></p><h3 id="不想要演示数据" tabindex="-1">不想要演示数据 <a class="header-anchor" href="#不想要演示数据" aria-label="Permalink to &quot;不想要演示数据&quot;">​</a></h3><p>种子分两类：<strong>系统基线</strong>（身份/权限/菜单/字典等，始终播种，是应用能跑的最小骨架）与<strong>演示数据</strong>（示例组织、演示账号、演示业务租户）。把 <code>Saas:Seed:EnableDemoData</code> 显式设为 <code>false</code> 即整体跳过演示种子；<strong>缺省或非法值都视为启用</strong>。</p><hr><h2 id="认证与令牌" tabindex="-1">认证与令牌 <a class="header-anchor" href="#认证与令牌" aria-label="Permalink to &quot;认证与令牌&quot;">​</a></h2><h3 id="怎么获取-token" tabindex="-1">怎么获取 token？ <a class="header-anchor" href="#怎么获取-token" aria-label="Permalink to &quot;怎么获取 token？&quot;">​</a></h3><p><code>POST /api/Auth/Login</code>，body 传 <code>username</code>（<strong>邮箱</strong>）+ <code>password</code>，成功后从 <code>data.token.accessToken</code> 取。完整流程（含 2FA 分支、验证码登录、刷新、切租户）与可直接照抄的 curl 见 <a href="./api-guide#怎么获取-token-完整实操">接口对接指南 · 怎么获取 token</a>。</p><h3 id="登录一直提示账号或密码错误" tabindex="-1">登录一直提示账号或密码错误 <a class="header-anchor" href="#登录一直提示账号或密码错误" aria-label="Permalink to &quot;登录一直提示账号或密码错误&quot;">​</a></h3><p><code>username</code> 字段要传<strong>邮箱</strong>——邮箱是全平台唯一登录标识；只有平台账号（<code>TenantId=0</code>，如超管）才可以用用户名登录。</p><h3 id="接口一直-401-甚至陷入「刷新-→-401-→-刷新」" tabindex="-1">接口一直 401，甚至陷入「刷新 → 401 → 刷新」 <a class="header-anchor" href="#接口一直-401-甚至陷入「刷新-→-401-→-刷新」" aria-label="Permalink to &quot;接口一直 401，甚至陷入「刷新 → 401 → 刷新」&quot;">​</a></h3><p>按这个顺序查：</p><ol><li>请求头写全了吗：<code>Authorization: Bearer &lt;accessToken&gt;</code>，<code>Bearer</code> 后有一个空格。</li><li>Access Token 默认 60 分钟就过期了，要用 <code>POST /api/Auth/RefreshToken</code> 换新，<strong>必须同时提交旧 <code>accessToken</code> 与 <code>refreshToken</code></strong>，缺一即失败。</li><li>Refresh Token 默认 7 天，过期只能重新登录。</li><li>会话被撤销（管理员踢下线、删除用户、超出最大设备数被顶）后，令牌即便没过期也不再有效。</li></ol><p>前端 <code>RequestClient</code> 已内建自动刷新与并发排队，刷新请求自身带 <code>_isRefresh</code> 标记不会再次触发刷新，不存在死循环；如果你在裸调接口，自己实现时也要加这个标记。</p><h3 id="接口返回-423-前端弹回了登录页" tabindex="-1">接口返回 423，前端弹回了登录页 <a class="header-anchor" href="#接口返回-423-前端弹回了登录页" aria-label="Permalink to &quot;接口返回 423，前端弹回了登录页&quot;">​</a></h3><p><strong>423 不是 401</strong>。它表示会话被锁屏——用户身份<strong>仍然有效</strong>，只是当前会话锁住了。正确处理是弹出解锁遮罩、调 <code>POST /api/Auth/UnlockSession</code>，<strong>不要</strong>清 token 跳登录页。</p><h3 id="给用户加了权限-需要重新登录才生效吗" tabindex="-1">给用户加了权限，需要重新登录才生效吗？ <a class="header-anchor" href="#给用户加了权限-需要重新登录才生效吗" aria-label="Permalink to &quot;给用户加了权限，需要重新登录才生效吗？&quot;">​</a></h3><p><strong>不需要</strong>。权限码不冻结进 JWT（超管例外，只放一个通配 <code>*</code> 作快路径），鉴权走服务端<strong>授权快照</strong>实时判定，授予/回收立刻生效。</p><h3 id="切换租户会不会把我原来的登录顶掉" tabindex="-1">切换租户会不会把我原来的登录顶掉？ <a class="header-anchor" href="#切换租户会不会把我原来的登录顶掉" aria-label="Permalink to &quot;切换租户会不会把我原来的登录顶掉？&quot;">​</a></h3><p>不会。切租户是<strong>复用当前会话轮换令牌</strong>：不发登录事件、不新增设备记录。调 <code>POST /api/Auth/SwitchTenant</code>，<code>tenantId</code> 传 <code>null</code> 即回到平台运维态。</p><hr><h2 id="权限与菜单" tabindex="-1">权限与菜单 <a class="header-anchor" href="#权限与菜单" aria-label="Permalink to &quot;权限与菜单&quot;">​</a></h2><h3 id="新加的菜单在前端不显示" tabindex="-1">新加的菜单在前端不显示 <a class="header-anchor" href="#新加的菜单在前端不显示" aria-label="Permalink to &quot;新加的菜单在前端不显示&quot;">​</a></h3><p>菜单种子是 <strong>fail-closed</strong> 的：<code>SaasMenuSeeder</code> 先按 <code>PermissionCode</code> 去查 <code>SysPermission</code>，<strong>查不到就跳过该菜单并打 Warning</strong>（日志里搜「依赖权限 ... 不存在，跳过初始化」）。所以：</p><ol><li>权限码得先在 <code>SaasPermissionCodes</code> 里定义，并追加进 <code>All</code>；</li><li>权限<strong>定义</strong>要加进 <code>SaasPermissionDefinitions.Groups</code>（这才是落库的那份），权限种子 <code>Order=20</code> 必须排在菜单种子 <code>Order=25</code> 之前；</li><li><code>PageRegistry</code> 里父目录要排在子项之前（种子按顺序解析 <code>ParentId</code>）；</li><li>新增独立模块时，种子链必须保持「<strong>操作 → 资源 → 权限 → 菜单 → 角色授权</strong>」完整顺序，缺了 <code>SysOperationSeeder</code> 会让整条链静默失效（权限由「资源 × 操作」派生）。</li></ol><p>改完重建库或重跑种子。详见 <a href="./backend/development#接线点检查清单">二次开发 · 接线点检查清单</a>。</p><h3 id="菜单出来了-但点进去-404-白屏" tabindex="-1">菜单出来了，但点进去 404 / 白屏 <a class="header-anchor" href="#菜单出来了-但点进去-404-白屏" aria-label="Permalink to &quot;菜单出来了，但点进去 404 / 白屏&quot;">​</a></h3><p>后端 <code>PageDescriptor.Component</code> 决定前端视图落点：约定 <code>Component</code> = <code>Path</code> 去掉前导斜杠 + <code>/index</code>，对应 <code>frontend/src/views/**/index.vue</code>，由 <code>import.meta.glob</code> 匹配。</p><p>例外是 <code>_core</code> 页面（个人中心、仪表盘、关于页等，落在 <code>packages/views/_core</code>）：<code>Component</code> 写 <code>_core/xxx/index</code>，<strong>必须同时在 <code>packages/router/dynamic.ts</code> 的 <code>coreComponentMap</code> 里登记</strong>，否则匹配不到组件、回退 not-found。</p><h3 id="我有这个权限码-接口还是-403" tabindex="-1">我有这个权限码，接口还是 403 <a class="header-anchor" href="#我有这个权限码-接口还是-403" aria-label="Permalink to &quot;我有这个权限码，接口还是 403&quot;">​</a></h3><p>依次排查：</p><ol><li><strong>租户版本（Edition）门控</strong>：租户所属版本的权限白名单没放行该权限码，运行时会被拦掉。</li><li><strong>数据范围</strong>：权限码通过了，但数据范围（本人 / 部门 / 部门及下级 / 租户）把这条记录挡在外面——表现常是「有权限但查不到数据」而非 403。</li><li><strong>约束规则引擎</strong>：SSD/DSD、互斥、时间窗、IP 等约束命中，被拒绝。</li><li><strong>权限委托已到期</strong>或被撤销。</li></ol><p>完整判定链见 <a href="./backend/permission">权限模型</a>。</p><h3 id="列表少了几列-排序点了没反应" tabindex="-1">列表少了几列 / 排序点了没反应 <a class="header-anchor" href="#列表少了几列-排序点了没反应" aria-label="Permalink to &quot;列表少了几列 / 排序点了没反应&quot;">​</a></h3><p><strong>字段级安全（FLS）在服务端门控</strong>：读侧经 <code>IFieldSecurityService.GuardFiltersAsync</code> / <code>GuardSortsAsync</code> 过滤，<strong>只有「可读且未脱敏」的字段</strong>才允许参与过滤与排序，其余被静默剔除；剔完没有有效排序时回退默认排序。前端 Schema 页也会按字段 <code>permission</code> 直接不渲染该列。所以是权限问题，不是 bug。</p><hr><h2 id="接口与联调" tabindex="-1">接口与联调 <a class="header-anchor" href="#接口与联调" aria-label="Permalink to &quot;接口与联调&quot;">​</a></h2><h3 id="新加的分页方法收不到请求体" tabindex="-1">新加的分页方法收不到请求体 <a class="header-anchor" href="#新加的分页方法收不到请求体" aria-label="Permalink to &quot;新加的分页方法收不到请求体&quot;">​</a></h3><p>分页方法<strong>必须显式标 <code>[HttpPost]</code></strong>。方法名以 <code>Get</code> 开头会被动态 API 约定推导成 GET，body 自然绑不上。</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PermissionAuthorize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SaasPermissionCodes.Position.Read)]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HttpPost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← 别漏</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Task</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PageResultDtoBase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PositionListItemDto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetPositionPageAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    PositionPageQueryDto</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CancellationToken</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cancellationToken</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { … }</span></span></code></pre></div><h3 id="生成的路由和我预期的不一样" tabindex="-1">生成的路由和我预期的不一样 <a class="header-anchor" href="#生成的路由和我预期的不一样" aria-label="Permalink to &quot;生成的路由和我预期的不一样&quot;">​</a></h3><p>动态 API 按方法名推导路由，三条容易忘的规则：</p><ol><li><strong>动词前缀被剥离</strong>：<code>GetUserPageAsync</code> → 动作名 <code>UserPage</code>（不是 <code>GetUserPage</code>）。</li><li><strong>无匹配动词前缀时默认 POST</strong>：<code>SwitchTenantAsync</code> → <code>POST /api/Auth/SwitchTenant</code>。</li><li><strong>路由段只由显式 <code>[FromRoute]</code> 参数产生</strong>。普通参数一律走查询串或 body，<strong>不会</strong>变成 <code>/{id}</code> 路径段。想要 <code>/api/User/User/{id}</code> 必须给参数标 <code>[FromRoute]</code>。</li></ol><p>前缀匹配要求词边界（前缀后必须是大写字母或下划线），所以 <code>AddressBook</code> 不会被 <code>Add</code> 命中。完整推导表见 <a href="./api-guide#动态-api-路由推导规则">接口对接指南</a>。</p><h3 id="返回的-id-变成了字符串" tabindex="-1">返回的 ID 变成了字符串 <a class="header-anchor" href="#返回的-id-变成了字符串" aria-label="Permalink to &quot;返回的 ID 变成了字符串&quot;">​</a></h3><p>框架把 <strong><code>long</code> 统一序列化为 JSON 字符串</strong>，避免 JavaScript Number 精度溢出（雪花 ID 会溢出 53 位安全整数）。前端类型标成 <code>string</code>，需要运算时显式 <code>Number()</code>。反序列化时数字与字符串都接受。</p><h3 id="响应里某个字段整个不见了" tabindex="-1">响应里某个字段整个不见了 <a class="header-anchor" href="#响应里某个字段整个不见了" aria-label="Permalink to &quot;响应里某个字段整个不见了&quot;">​</a></h3><p>服务端 <code>DefaultIgnoreCondition = WhenWritingNull</code>：<strong>值为 null 的字段直接不输出</strong>。客户端把字段按可选处理，别用「字段存在与否」判断成功——判定成功请读 <code>isSuccess</code>。</p><h3 id="oauthproviders-还是-oauthproviders" tabindex="-1"><code>oAuthProviders</code> 还是 <code>oauthProviders</code>？ <a class="header-anchor" href="#oauthproviders-还是-oauthproviders" aria-label="Permalink to &quot;`oAuthProviders` 还是 `oauthProviders`？&quot;">​</a></h3><p><code>oAuthProviders</code>。camelCase 命名策略只把<strong>首字母</strong>变小写，<code>OAuthProviders</code> → <code>oAuthProviders</code>。同类还有 <code>oAuthApps</code> 等，抄字段名时留意。</p><h3 id="时间显示差了几个小时" tabindex="-1">时间显示差了几个小时 <a class="header-anchor" href="#时间显示差了几个小时" aria-label="Permalink to &quot;时间显示差了几个小时&quot;">​</a></h3><p>后端<strong>存储恒为 UTC</strong>，输出时按请求头 <code>X-Timezone</code>（IANA 标识，如 <code>Asia/Shanghai</code>）换算。不发这个头就按服务端默认时区输出。前端已在请求拦截器里自动带上（用户已选时区优先，否则跟随浏览器 <code>Intl</code>）。</p><h3 id="枚举值到底发数字还是发字符串" tabindex="-1">枚举值到底发数字还是发字符串？ <a class="header-anchor" href="#枚举值到底发数字还是发字符串" aria-label="Permalink to &quot;枚举值到底发数字还是发字符串？&quot;">​</a></h3><ul><li><strong>响应</strong>：枚举输出为<strong>成员名字符串</strong>（如 <code>&quot;Enabled&quot;</code>）。唯一例外是 <code>ApiResponse.code</code>，恒为 int。</li><li><strong>请求</strong>：数字和成员名都接受。前端契约层统一发数字（<code>QueryOperator.Between</code> = <code>4000</code> 等）。</li></ul><hr><h2 id="后端开发" tabindex="-1">后端开发 <a class="header-anchor" href="#后端开发" aria-label="Permalink to &quot;后端开发&quot;">​</a></h2><h3 id="运行期-di-解析不到我的领域服务" tabindex="-1">运行期 DI 解析不到我的领域服务 <a class="header-anchor" href="#运行期-di-解析不到我的领域服务" aria-label="Permalink to &quot;运行期 DI 解析不到我的领域服务&quot;">​</a></h3><p><strong>领域服务必须手写注册</strong>。领域服务接口不带 <code>IScopedDependency</code> / <code>IDomainService</code> 之类的 DI 标记接口，框架的约定注册扫不到它，得在 <code>Extensions/ServiceCollectionExtensions.cs</code> 的 <code>AddSaasDomainServices</code>（或模块自己的对应方法）里显式登记：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddScoped</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IPositionDomainService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PositionDomainService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();</span></span></code></pre></div><p>对比之下：<strong>仓储</strong>（继承 <code>SaasRepository</code> → <code>IScopedDependency</code>）和<strong>应用服务 / 查询服务</strong>（实现 <code>IApplicationService</code>）都由约定自动注册，不用手写。这是纵切片最常见的漏接线点。</p><h3 id="我覆盖了框架的默认实现-但跑起来还是默认的" tabindex="-1">我覆盖了框架的默认实现，但跑起来还是默认的 <a class="header-anchor" href="#我覆盖了框架的默认实现-但跑起来还是默认的" aria-label="Permalink to &quot;我覆盖了框架的默认实现，但跑起来还是默认的&quot;">​</a></h3><p>框架模块用 <strong><code>TryAdd</code></strong> 先注册默认实现（<code>IPermissionChecker</code>、<code>IUserStore</code>、<code>IJobStore</code>、<code>IAiProviderConfigStore</code>、各 Bot <code>*ConfigStore</code> 等），你<strong>再 <code>TryAdd</code> 会被静默忽略</strong>。覆盖必须用 <code>Replace</code>：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">services.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Replace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ServiceDescriptor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IAiProviderConfigStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaasAiProviderConfigStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;());</span></span></code></pre></div><h3 id="事件处理器不触发" tabindex="-1">事件处理器不触发 <a class="header-anchor" href="#事件处理器不触发" aria-label="Permalink to &quot;事件处理器不触发&quot;">​</a></h3><p>本地事件总线只自动发现「<strong>以接口为服务类型</strong>」的注册，裸 <code>services.AddTransient&lt;具体处理器&gt;()</code> <strong>不会被订阅、静默失败</strong>。处理器必须显式加入 <code>XiHanLocalEventBusOptions.Handlers</code>——Saas 封装了 <code>AddSaasLocalEventHandler&lt;T&gt;()</code>（内部 <code>AddTransient</code> + <code>Configure&lt;XiHanLocalEventBusOptions&gt;(o =&gt; o.Handlers.AddIfNotContains(typeof(T)))</code>），在 <code>AddSaasEventHandlers</code> 里登记即可。</p><h3 id="匿名-minimal-api-端点调应用服务时永久挂起" tabindex="-1">匿名 Minimal API 端点调应用服务时永久挂起 <a class="header-anchor" href="#匿名-minimal-api-端点调应用服务时永久挂起" aria-label="Permalink to &quot;匿名 Minimal API 端点调应用服务时永久挂起&quot;">​</a></h3><p>匿名端点没有工作单元中间件，而应用服务被 Castle 代理包着，拦截器会急切开事务从而死锁。解法是<strong>绕开代理</strong>：注入真正的依赖直连，或用 <code>ProxyHelper.UnProxy</code> 取出真实目标实例再调。仓库里的 OAuth 回调端点就是这么处理的（<code>ExternalLoginAsync</code> 标 <code>[DynamicApi(IsEnabled = false)]</code> 不对外暴露，只由回调端点经未代理实例调用）。</p><h3 id="数据变更日志-diff-一条都没有" tabindex="-1">数据变更日志（Diff）一条都没有 <a class="header-anchor" href="#数据变更日志-diff-一条都没有" aria-label="Permalink to &quot;数据变更日志（Diff）一条都没有&quot;">​</a></h3><p>需要两个条件同时成立：</p><ol><li>配置 <strong><code>XiHan:Data:SqlSugarCore:EnableDiffLog</code> 设为 <code>true</code></strong>（<strong>默认是 <code>false</code></strong>，不开则 AOP 不挂载、差异被直接丢弃）；</li><li>写操作走仓储并显式调用了 <code>.EnableDiffLogEvent(businessData)</code>。</li></ol><p>生产环境的 <code>appsettings</code> 常被 gitignore，容易漏配，记得在服务器上单独补。另外只有走仓储的写才会被覆盖到。</p><h3 id="部署后接口报-42703-column-does-not-exist" tabindex="-1">部署后接口报 <code>42703 column does not exist</code> <a class="header-anchor" href="#部署后接口报-42703-column-does-not-exist" aria-label="Permalink to &quot;部署后接口报 `42703 column does not exist`&quot;">​</a></h3><p><code>DbInitializer</code> <strong>表存在就跳过创建</strong>（日志里是「表已存在，跳过创建」），它<strong>从不为已有表补列</strong>。所以给既有实体加字段后部署必炸。</p><p>不要依赖 CodeFirst 给已有表补列。正式版本应在 <code>WebHost/UpdateScripts/{version}.sql</code> 中加入前向迁移，升级引擎会按版本执行并记录到 <code>SysMigrationHistory</code>；临时环境也可重建库或手工 <code>ALTER TABLE</code>。</p><h3 id="本地-dotnet-build-报文件被占用" tabindex="-1">本地 <code>dotnet build</code> 报文件被占用 <a class="header-anchor" href="#本地-dotnet-build-报文件被占用" aria-label="Permalink to &quot;本地 `dotnet build` 报文件被占用&quot;">​</a></h3><p>运行中的应用会锁住 DLL。停掉正在运行的实例再构建。后端由部署流程在服务器上构建/发布，本地改动需部署后才生效，线上诊断以加日志为主。</p><hr><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="页面整片白屏-控制台报-invalid-linked-format" tabindex="-1">页面整片白屏，控制台报 <code>Invalid linked format</code> <a class="header-anchor" href="#页面整片白屏-控制台报-invalid-linked-format" aria-label="Permalink to &quot;页面整片白屏，控制台报 `Invalid linked format`&quot;">​</a></h3><p>语言包文案里出现了<strong>裸 <code>@</code></strong>（如 <code>联系 @admin</code>）。vue-i18n 会把 <code>@</code> 当作 linked message 语法解析并抛错。必须转义成 <code>{&#39;@&#39;}</code>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ 白屏</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;联系 @admin&#39;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;联系 {&#39;@&#39;}admin&quot;</span></span></code></pre></div><p>新增文案前先扫一遍裸 <code>@</code>。</p><h3 id="图标显示成空白" tabindex="-1">图标显示成空白 <a class="header-anchor" href="#图标显示成空白" aria-label="Permalink to &quot;图标显示成空白&quot;">​</a></h3><p>图标走 Iconify <strong>离线模式</strong>，运行期只保证 <strong><code>lucide</code> / <code>tabler</code> / <code>mdi</code> / <code>simple-icons</code></strong> 这四个已预加载的图标集能直接渲染。用了未预加载的集（carbon / ep / heroicons 等）会渲染为空——离线 <code>Icon</code> 对已挂载组件不会因后加载而重渲染。品牌图标优先用 <code>simple-icons:*</code> 或 <code>tabler:brand-*</code>。</p><h3 id="上传的文件在线上打不开-404" tabindex="-1">上传的文件在线上打不开（404） <a class="header-anchor" href="#上传的文件在线上打不开-404" aria-label="Permalink to &quot;上传的文件在线上打不开（404）&quot;">​</a></h3><p>本地存储返回的是<strong>根相对路径</strong> <code>/uploads/...</code>。前后端同源没问题，<strong>线上前后端不同源时必须拼上 <code>VITE_API_BASE_URL</code> 的 origin</strong>。仓库里的 <code>toAbsoluteFileUrl</code> / <code>useAvatarUrl</code> 已经处理了这件事，自己拼 URL 时别忘了。</p><h3 id="跑-lint-把不相干的文件改坏了" tabindex="-1">跑 lint 把不相干的文件改坏了 <a class="header-anchor" href="#跑-lint-把不相干的文件改坏了" aria-label="Permalink to &quot;跑 lint 把不相干的文件改坏了&quot;">​</a></h3><p><code>pnpm run lint:fix</code> 展开是 <code>oxlint --fix &amp;&amp; eslint . --fix</code>，会扫全仓并改动与你无关的文件。<strong>只对本次改动的文件跑</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eslint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/views/identity/position/index.vue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><p>误跑了就 <code>git checkout HEAD -- &lt;非本次任务的文件&gt;</code> 还原。</p><hr><h2 id="部署与运维" tabindex="-1">部署与运维 <a class="header-anchor" href="#部署与运维" aria-label="Permalink to &quot;部署与运维&quot;">​</a></h2><h3 id="升级版本要写数据迁移吗" tabindex="-1">升级版本要写数据迁移吗？ <a class="header-anchor" href="#升级版本要写数据迁移吗" aria-label="Permalink to &quot;升级版本要写数据迁移吗？&quot;">​</a></h3><p><strong>要写前向 SQL 迁移。</strong> 首次部署由 CodeFirst 建库建表；已有数据库的变更放入 <code>WebHost/UpdateScripts/{version}.sql</code>。升级引擎具备逐库执行、台账与失败状态能力，但当前 BasicApp 没有调用执行入口，启动不会自动跑脚本；发布流程必须显式补齐或外置唯一迁移步骤。当前脚本为 PostgreSQL 方言，切换数据库时需提供对应实现。详见<a href="./backend/upgrade">升级与迁移</a>。</p><h3 id="启用-ai-知识库-rag-前要准备什么" tabindex="-1">启用 AI 知识库（RAG）前要准备什么？ <a class="header-anchor" href="#启用-ai-知识库-rag-前要准备什么" aria-label="Permalink to &quot;启用 AI 知识库（RAG）前要准备什么？&quot;">​</a></h3><p>需要先部署 <strong>Qdrant 向量库</strong>并配好 <code>XiHan:AI:Rag</code> 连接参数。全新数据库会自动创建 RAG 表并执行种子；存量库应随版本升级脚本迁移。见 <a href="./backend/ai">AI 能力</a> 与 <a href="./dev-environment#向量数据库-qdrant-可选-ai-知识库用">开发环境 · Qdrant</a>。</p><h3 id="怎么定位一次线上请求" tabindex="-1">怎么定位一次线上请求？ <a class="header-anchor" href="#怎么定位一次线上请求" aria-label="Permalink to &quot;怎么定位一次线上请求？&quot;">​</a></h3><p>每个响应都带 <code>traceId</code>（信封字段）与 <code>X-Trace-Id</code> 响应头。拿它去日志、审计日志、链路时间线里检索，就能串起这一次请求的访问 / API / 操作 / 异常 / 实体变更全部记录。启用 OpenTelemetry（<code>XiHan:Observability</code>，<strong>默认关闭</strong>）后该值就是 W3C 的 32-hex TraceId，可直接在 Jaeger / Tempo 里查。</p><hr><h2 id="还没解决" tabindex="-1">还没解决？ <a class="header-anchor" href="#还没解决" aria-label="Permalink to &quot;还没解决？&quot;">​</a></h2><ul><li><a href="./api-guide">接口对接指南</a>：响应信封、业务码、请求头、分页协议的完整规范</li><li><a href="./backend/development">二次开发</a>：新增功能的完整接线清单（漏哪一步会怎样）</li><li><a href="./backend/permission">权限模型</a>：403 / 查不到数据的判定链</li><li><a href="https://framework.docs.xihanfun.com/guide/faq" target="_blank" rel="noreferrer">框架常见问题</a>：模块装配、DI、事务、拦截器层面的坑</li><li>仍未解决可到 <a href="https://github.com/XiHanFun/XiHan.BasicApp/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提问，附上 <code>traceId</code> 与复现步骤</li></ul>',118)])])}const k=a(t,[["render",d]]);export{g as __pageData,k as default};
